def check(call, view, history):
    if call.name != "transfer_to_human_agents":
        return None
    orders = view.get("orders", {})
    if not isinstance(orders, dict):
        return None
    active = {"pending", "delivered", "exchange requested"}
    if any(isinstance(order, dict) and order.get("status") in active for order in orders.values()):
        return "Do not escalate yet: an active order workflow remains unresolved. Review every requested order operation, perform the applicable supported operation after confirmation, and verify its resulting status before escalating."
    return None
